{"id":"c0b2e94e-2dfa-4487-a2e3-75215e0207d9","inserted_at":"2026-07-08T00:17:52.273332+00:00","updated_at":"2026-07-08T00:17:52.273332+00:00","type":"sql","name":"Untitled query","description":"","content":{"sql":"-- ==========================================\r\n-- FIX VISTA E COLORI TENANT\r\n-- Assicura che i colori verdi di Taranto siano corretti\r\n-- ==========================================\r\n\r\nUPDATE public.tenants\r\nSET \r\n  primary_color = '#4A5D23',\r\n  secondary_color = '#D96C4A',\r\n  logo_url = 'https://lotohub.s3.amazonaws.com/tenants/taranto/logo.png'\r\nWHERE slug = 'taranto';\r\n\r\n-- Per sicurezza, ricreiamo la vista senza restrizioni RLS\r\nDROP VIEW IF EXISTS public.vw_pois_frontend;\r\nCREATE VIEW public.vw_pois_frontend AS\r\nSELECT \r\n    p.id,\r\n    p.name,\r\n    p.category,\r\n    p.layer_name,\r\n    p.xp_reward,\r\n    p.checkin_radius,\r\n    p.loto_quota_max,\r\n    p.is_accessible,\r\n    p.is_active,\r\n    ST_Y(p.coords::geometry) AS lat,\r\n    ST_X(p.coords::geometry) AS lng,\r\n    p.territory_id,\r\n    LOWER(t.name) AS tenant_id\r\nFROM public.pois p\r\nLEFT JOIN public.territories t ON p.territory_id = t.id;\r\n\r\nGRANT SELECT ON public.vw_pois_frontend TO authenticated, anon;","content_id":"c0b2e94e-2dfa-4487-a2e3-75215e0207d9","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
